using RealmForge.Domain.Entities;
using RealmForge.Shared.Enums;

namespace RealmForge.Infrastructure.Persistence.Seeding.RulesGlossaryData;

///	<summary>
///	Actions of the 2024 rules. English text from the SRD 5.2.1 (CC BY 4.0); the Italian texts are RealmForge
///	translations that use the official names of the Italian Player's Handbook.
///	</summary>
public static class GlossaryActions2024Seeder
{
	public static IEnumerable<RuleEntry> Build()
	{
		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2024, ContentSource.Srd52, "attack", RuleCategory.Action,
			related: Array.Empty<string>(),
			en: ("Attack", "When you take the Attack action, you can make one attack roll with a weapon or an Unarmed Strike.\n\n**Equipping and Unequipping Weapons.** You can either equip or unequip one weapon when you make an attack as part of this action. You do so either before or after the attack. If you equip a weapon before an attack, you don't need to use it for that attack. Equipping a weapon includes drawing it from a sheath or picking it up. Unequipping a weapon includes sheathing, stowing, or dropping it.\n\n**Moving between Attacks.** If you move on your turn and have a feature, such as Extra Attack, that gives you more than one attack as part of the Attack action, you can use some or all of that movement to move between those attacks.",
				new[] { "Attack action" }),
			it: ("Attacco", "Quando effettua l'azione di Attacco, il personaggio può compiere un tiro per colpire con un'arma o con un colpo senz'armi.\n\n**Impugnare e riporre le armi.** Ogni volta che attacca nell'ambito di questa azione, il personaggio può impugnare o riporre un'arma, prima o dopo l'attacco. Se impugna un'arma prima di attaccare, non è obbligato a usarla per quell'attacco. Impugnare un'arma significa anche estrarla dal fodero o raccoglierla; riporla significa anche rinfoderarla, metterla via o lasciarla cadere.\n\n**Muoversi tra un attacco e l'altro.** Se il personaggio si muove nel suo turno e ha un privilegio, come Attacco Extra, che gli concede più attacchi con l'azione di Attacco, può usare parte o tutto il suo movimento tra un attacco e l'altro.",
				new[] { "azione di Attacco", "azione Attacco" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2024, ContentSource.Srd52, "dash", RuleCategory.Action,
			related: new[] { "speed" },
			en: ("Dash", "When you take the Dash action, you gain extra movement for the current turn. The increase equals your Speed after applying any modifiers. With a Speed of 30 feet, for example, you can move up to 60 feet on your turn if you Dash. If your Speed of 30 feet is reduced to 15 feet, you can move up to 30 feet this turn if you Dash.\n\nIf you have a special speed, such as a Fly Speed or Swim Speed, you can use that speed instead of your Speed when you take this action. You choose which speed to use each time you take it.",
				new[] { "Dash action" }),
			it: ("Scatto", "Quando effettua l'azione di Scatto, il personaggio ottiene movimento aggiuntivo per il turno in corso, pari alla sua velocità dopo aver applicato gli eventuali modificatori. Con una velocità di 9 metri, per esempio, può muoversi fino a 18 metri nel suo turno se scatta; se la sua velocità di 9 metri è ridotta a 4,5 metri, scattando può muoversi fino a 9 metri in quel turno.\n\nSe ha una velocità speciale, come una velocità di volo o di nuoto, può usarla al posto della velocità normale quando effettua questa azione, scegliendo ogni volta quale usare.",
				new[] { "azione di Scatto", "azione Scatto" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2024, ContentSource.Srd52, "disengage", RuleCategory.Action,
			related: Array.Empty<string>(),
			en: ("Disengage", "If you take the Disengage action, your movement doesn't provoke Opportunity Attacks for the rest of the current turn.",
				new[] { "Disengage action" }),
			it: ("Disimpegno", "Se il personaggio effettua l'azione di Disimpegno, il suo movimento non provoca attacchi di opportunità per il resto del turno in corso.",
				new[] { "azione di Disimpegno", "azione Disimpegno" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2024, ContentSource.Srd52, "dodge", RuleCategory.Action,
			related: Array.Empty<string>(),
			en: ("Dodge", "If you take the Dodge action, you gain the following benefits: until the start of your next turn, any attack roll made against you has Disadvantage if you can see the attacker, and you make Dexterity saving throws with Advantage.\n\nYou lose these benefits if you have the Incapacitated condition or if your Speed is 0.",
				new[] { "Dodge action" }),
			it: ("Schivata", "Se il personaggio effettua l'azione di Schivata, ottiene questi benefici fino all'inizio del suo turno successivo: i tiri per colpire contro di lui subiscono svantaggio se può vedere l'attaccante, e ha vantaggio ai tiri salvezza su Destrezza.\n\nPerde questi benefici se ha la condizione di incapacitato o se la sua velocità è 0.",
				new[] { "azione di Schivata", "azione Schivata" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2024, ContentSource.Srd52, "help", RuleCategory.Action,
			related: Array.Empty<string>(),
			en: ("Help", "When you take the Help action, you do one of the following.\n\n**Assist an Ability Check.** Choose one of your skill or tool proficiencies and one ally who is near enough for you to assist verbally or physically when they make an ability check. That ally has Advantage on the next ability check they make with the chosen skill or tool. This benefit expires if the ally doesn't use it before the start of your next turn. The GM has final say on whether your assistance is possible.\n\n**Assist an Attack Roll.** You momentarily distract an enemy within 5 feet of you, giving Advantage to the next attack roll by one of your allies against that enemy. This benefit expires at the start of your next turn.",
				new[] { "Help action" }),
			it: ("Aiuto", "Quando effettua l'azione di Aiuto, il personaggio sceglie una di queste opzioni.\n\n**Aiutare in una prova di caratteristica.** Il personaggio sceglie una delle abilità o degli strumenti in cui ha competenza e un alleato abbastanza vicino da poterlo assistere, a parole o fisicamente, in una prova di caratteristica. Quell'alleato ha vantaggio alla prossima prova di caratteristica che effettua con l'abilità o lo strumento scelto. Il beneficio svanisce se l'alleato non lo usa prima dell'inizio del turno successivo del personaggio. Spetta al DM l'ultima parola sulla possibilità di prestare aiuto.\n\n**Aiutare in un tiro per colpire.** Il personaggio distrae per un attimo un nemico entro 1,5 metri da lui, concedendo vantaggio al prossimo tiro per colpire di un suo alleato contro quel nemico. Il beneficio svanisce all'inizio del turno successivo del personaggio.",
				new[] { "azione di Aiuto", "azione Aiuto" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2024, ContentSource.Srd52, "hide", RuleCategory.Action,
			related: Array.Empty<string>(),
			en: ("Hide", "With the Hide action, you try to hide yourself. To do so, you must succeed on a DC 15 Dexterity (Stealth) check while you're Heavily Obscured or behind Three-Quarters Cover or Total Cover, and you must be out of any enemy's line of sight; if you can see a creature, you can discern whether it can see you.\n\nOn a successful check, you have the Invisible condition while hidden. Make note of your check's total, which is the DC for a creature to find you with a Wisdom (Perception) check.\n\nYou stop being hidden immediately after any of the following occurs: you make a sound louder than a whisper, an enemy finds you, you make an attack roll, or you cast a spell with a Verbal component.",
				new[] { "Hide action" }),
			it: ("Nascondersi", "Con l'azione di Nascondersi, il personaggio cerca di celarsi alla vista. Per riuscirci deve superare una prova di Destrezza (Furtività) con CD 15 mentre si trova in pesante oscurità o dietro copertura di tre quarti o totale, e deve essere fuori dalla linea di vista di tutti i nemici; se può vedere una creatura, sa anche se quella creatura può vedere lui.\n\nSe supera la prova, il personaggio ha la condizione di invisibile finché resta nascosto. Il totale della sua prova diventa la CD che una creatura deve superare con una prova di Saggezza (Percezione) per trovarlo.\n\nIl personaggio smette di essere nascosto non appena accade una di queste cose: emette un suono più forte di un sussurro, un nemico lo trova, effettua un tiro per colpire o lancia un incantesimo con una componente verbale.",
				new[] { "azione di Nascondersi", "azione Nascondersi" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2024, ContentSource.Srd52, "influence", RuleCategory.Action,
			related: Array.Empty<string>(),
			en: ("Influence", "With the Influence action, you urge a monster to do something. Describe or roleplay how you're communicating with the monster. Are you trying to deceive, intimidate, amuse, or gently persuade? The GM then determines whether the monster feels willing, unwilling, or hesitant due to your interaction; this determination establishes whether an ability check is necessary, as explained below.\n\n**Willing.** If your urging aligns with the monster's desires, no ability check is necessary; the monster fulfills your request in a way it prefers.\n\n**Unwilling.** If your urging is repugnant to the monster or counter to its alignment, no ability check is necessary; it doesn't comply.\n\n**Hesitant.** If you urge the monster to do something that it is hesitant to do, you must make an ability check, which is affected by the monster's attitude: Indifferent, Friendly, or Hostile, each of which is defined in this glossary. The Influence Checks table suggests which ability check to make based on how you're interacting with the monster. The GM chooses the check, which has a default DC equal to 15 or the monster's Intelligence score, whichever is higher. On a successful check, the monster does as urged. On a failed check, you must wait 24 hours (or a duration set by the GM) before urging it in the same way again.\n\n**Influence Checks**\n\n| Ability Check | Interaction |\n|---|---|\n| Charisma (Deception) | Deceiving a monster that understands you |\n| Charisma (Intimidation) | Intimidating a monster |\n| Charisma (Performance) | Amusing a monster |\n| Charisma (Persuasion) | Persuading a monster that understands you |\n| Wisdom (Animal Handling) | Gently coaxing a Beast or Monstrosity |",
				new[] { "Influence action" }),
			it: ("Influenza", "Con l'azione di Influenza, il personaggio esorta un mostro a fare qualcosa. Il giocatore descrive o interpreta il modo in cui il personaggio comunica con il mostro: sta cercando di ingannarlo, di intimidirlo, di divertirlo o di persuaderlo con garbo? In base all'interazione, il DM stabilisce se il mostro è ben disposto, mal disposto o esitante, e di conseguenza se serve una prova di caratteristica, come spiegato qui sotto.\n\n**Ben disposto.** Se la richiesta asseconda i desideri del mostro, non serve alcuna prova: il mostro la esaudisce nel modo che preferisce.\n\n**Mal disposto.** Se la richiesta ripugna al mostro o va contro il suo allineamento, non serve alcuna prova: il mostro non la esaudisce.\n\n**Esitante.** Se il personaggio esorta il mostro a fare qualcosa che esita a fare, deve effettuare una prova di caratteristica, influenzata dall'atteggiamento del mostro (indifferente, amichevole od ostile). La tabella \"Prove di Influenza\" suggerisce quale prova effettuare in base al modo in cui il personaggio interagisce con il mostro. Il DM sceglie la prova, la cui CD predefinita è pari a 15 o al punteggio di Intelligenza del mostro, a seconda di quale valore sia più alto. Se la prova riesce, il mostro fa ciò che gli è stato chiesto; se fallisce, il personaggio deve attendere 24 ore (o il tempo stabilito dal DM) prima di riprovare nello stesso modo.\n\n**Prove di Influenza**\n\n| Prova di caratteristica | Interazione |\n|---|---|\n| Carisma (Inganno) | Ingannare un mostro che comprende il personaggio |\n| Carisma (Intimidire) | Intimidire un mostro |\n| Carisma (Intrattenere) | Divertire un mostro |\n| Carisma (Persuasione) | Persuadere un mostro che comprende il personaggio |\n| Saggezza (Addestrare Animali) | Convincere con dolcezza una bestia o una mostruosità |",
				new[] { "azione di Influenza", "azione Influenza" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2024, ContentSource.Srd52, "magic", RuleCategory.Action,
			related: new[] { "concentration" },
			en: ("Magic", "When you take the Magic action, you cast a spell that has a casting time of an action or use a feature or magic item that requires a Magic action to be activated.\n\nIf you cast a spell that has a casting time of 1 minute or longer, you must take the Magic action on each turn of that casting, and you must maintain Concentration while you do so. If your Concentration is broken, the spell fails, but you don't expend a spell slot.",
				new[] { "Magic action" }),
			it: ("Magia", "Quando effettua l'azione di Magia, il personaggio lancia un incantesimo con tempo di lancio di un'azione, oppure usa un privilegio o un oggetto magico che richiede un'azione di Magia per essere attivato.\n\nSe lancia un incantesimo con tempo di lancio di 1 minuto o più, deve effettuare l'azione di Magia in ogni turno del lancio e mantenere la concentrazione per tutto il tempo. Se la concentrazione si interrompe, l'incantesimo fallisce, ma lo slot incantesimo non viene speso.",
				new[] { "azione di Magia", "azione Magia" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2024, ContentSource.Srd52, "ready", RuleCategory.Action,
			related: Array.Empty<string>(),
			en: ("Ready", "You take the Ready action to wait for a particular circumstance before you act. To do so, you take this action on your turn, which lets you act by taking a Reaction before the start of your next turn.\n\nFirst, you decide what perceivable circumstance will trigger your Reaction. Then, you choose the action you will take in response to that trigger, or you choose to move up to your Speed in response to it. Examples include \"If the cultist steps on the trapdoor, I'll pull the lever that opens it,\" and \"If the zombie steps next to me, I move away.\"\n\nWhen the trigger occurs, you can either take your Reaction right after the trigger finishes or ignore the trigger.\n\nWhen you Ready a spell, you cast it as normal (expending any resources used to cast it) but hold its energy, which you release with your Reaction when the trigger occurs. To be readied, a spell must have a casting time of an action, and holding on to the spell's magic requires Concentration, which you can maintain up to the start of your next turn. If your Concentration is broken, the spell dissipates without taking effect.",
				new[] { "Ready action" }),
			it: ("Prepararsi", "Il personaggio effettua l'azione di Prepararsi per attendere una circostanza specifica prima di agire. La effettua nel suo turno, e questo gli permette di agire con una reazione prima dell'inizio del suo turno successivo.\n\nPer prima cosa decide quale circostanza percepibile farà scattare la sua reazione; poi sceglie l'azione con cui risponderà, oppure decide di muoversi fino alla sua velocità in risposta. Per esempio: \"Se il cultista mette piede sulla botola, tiro la leva che la apre\" oppure \"Se lo zombi mi arriva accanto, mi allontano\".\n\nQuando la circostanza si verifica, il personaggio può effettuare la sua reazione subito dopo che è terminata, oppure ignorarla.\n\nQuando si prepara a lanciare un incantesimo, lo lancia normalmente (spendendo le risorse necessarie) ma ne trattiene l'energia, che libera con la sua reazione quando si verifica la circostanza. Per essere preparato, l'incantesimo deve avere un tempo di lancio di un'azione, e trattenerne la magia richiede concentrazione, che il personaggio può mantenere fino all'inizio del suo turno successivo. Se la concentrazione si interrompe, l'incantesimo si dissolve senza alcun effetto.",
				new[] { "azione di Prepararsi", "azione Prepararsi", "azione di Preparare", "azione Preparare" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2024, ContentSource.Srd52, "search", RuleCategory.Action,
			related: Array.Empty<string>(),
			en: ("Search", "When you take the Search action, you make a Wisdom check to discern something that isn't obvious. The Search table suggests which skills are applicable when you take this action, depending on what you're trying to detect.\n\n**Search**\n\n| Skill | Thing to Detect |\n|---|---|\n| Insight | Creature's state of mind |\n| Medicine | Creature's ailment or cause of death |\n| Perception | Concealed creature or object |\n| Survival | Tracks or food |",
				new[] { "Search action" }),
			it: ("Ricerca", "Quando effettua l'azione di Ricerca, il personaggio effettua una prova di Saggezza per individuare qualcosa che non è evidente. La tabella \"Ricerca\" suggerisce le abilità adatte in base a ciò che cerca.\n\n**Ricerca**\n\n| Abilità | Cosa individuare |\n|---|---|\n| Intuizione | Lo stato d'animo di una creatura |\n| Medicina | Il male di una creatura o la causa della sua morte |\n| Percezione | Una creatura o un oggetto nascosti |\n| Sopravvivenza | Tracce o cibo |",
				new[] { "azione di Ricerca", "azione Ricerca" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2024, ContentSource.Srd52, "study", RuleCategory.Action,
			related: Array.Empty<string>(),
			en: ("Study", "When you take the Study action, you make an Intelligence check to study your memory, a book, a clue, or another source of knowledge and call to mind an important piece of information about it.\n\nThe Areas of Knowledge table suggests which skills are applicable to various areas of knowledge.\n\n**Areas of Knowledge**\n\n| Skill | Areas |\n|---|---|\n| Arcana | Spells, magic items, eldritch symbols, magical traditions, planes of existence, and certain creatures (Aberrations, Constructs, Elementals, Fey, and Monstrosities) |\n| History | Historic events and people, ancient civilizations, wars, and certain creatures (Giants and Humanoids) |\n| Investigation | Traps, ciphers, riddles, and gadgetry |\n| Nature | Terrain, flora, weather, and certain creatures (Beasts, Dragons, Oozes, and Plants) |\n| Religion | Deities, religious hierarchies and rites, holy symbols, cults, and certain creatures (Celestials, Fiends, and Undead) |",
				new[] { "Study action" }),
			it: ("Studio", "Quando effettua l'azione di Studio, il personaggio effettua una prova di Intelligenza per esaminare la propria memoria, un libro, un indizio o un'altra fonte di conoscenza e richiamare alla mente un'informazione importante.\n\nLa tabella \"Aree di conoscenza\" suggerisce le abilità adatte ai vari campi del sapere.\n\n**Aree di conoscenza**\n\n| Abilità | Aree |\n|---|---|\n| Arcano | Incantesimi, oggetti magici, simboli occulti, tradizioni magiche, piani di esistenza e alcune creature (aberrazioni, costrutti, elementali, folletti e mostruosità) |\n| Storia | Eventi e personaggi storici, civiltà antiche, guerre e alcune creature (giganti e umanoidi) |\n| Indagare | Trappole, cifrari, enigmi e congegni |\n| Natura | Territori, flora, clima e alcune creature (bestie, draghi, melme e vegetali) |\n| Religione | Divinità, gerarchie e riti religiosi, simboli sacri, culti e alcune creature (celestiali, immondi e non morti) |",
				new[] { "azione di Studio", "azione Studio" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2024, ContentSource.Srd52, "utilize", RuleCategory.Action,
			related: Array.Empty<string>(),
			en: ("Utilize", "You normally interact with an object while doing something else, such as when you draw a sword as part of the Attack action. When an object requires an action for its use, you take the Utilize action.",
				new[] { "Utilize action" }),
			it: ("Utilizzo", "Di solito il personaggio interagisce con un oggetto mentre fa qualcos'altro, come quando estrae una spada nell'ambito dell'azione di Attacco. Quando un oggetto richiede un'azione per essere usato, il personaggio effettua l'azione di Utilizzo.",
				new[] { "azione di Utilizzo", "azione Utilizzo" }));
	}
}
